        const EMO_OK = ["\u{1F602}", "\u{1F60E}", "\u{1F525}", "\u{1F44F}", "\u{1F62D}", "\u{1F621}", "\u{1F92F}", "\u{1F389}", "\u{1F914}", "\u{1F440}", "\u{1F633}", "❤️"];
        const emoList = [], emoAt = new Map();
